preset.frame_eqs_eel:
warp=0;
le=1+.5+2*sin(bass_att);
bpulse=band(above(le,bth),above(le-bth,bblock));
bblock=le-bth;
bth=if(above(le,bth),le+114/(le+10)-7.407,
bth+bth*.07/(bth-12)+below(bth,2.7)*.1*(2.7-bth));
bth=if(above(bth,6),6,bth);
bres=bpulse*sin(pulse+le*.5) + bnot(bpulse)*bres;

le=1+.5+2*sin(treb_att);
tpulse=band(above(le,tth),above(le-tth,tblock));
tblock=le-tth;
tth=if(above(le,tth),le+114/(le+10)-7.407,
tth+tth*.07/(tth-12)+below(tth,2.7)*.1*(2.7-tth));
tth=if(above(tth,6),6,tth);
tres=tpulse*sin(pulse+le*.5) + bnot(tpulse)*tres;

le=1+.5+2*sin(mid_att);
mpulse=band(above(le,mth),above(le-mth,mblock));
mblock=le-mth;
mth=if(above(le,mth),le+114/(le+10)-7.407,
mth+mth*.07/(mth-12)+below(mth,2.7)*.1*(2.7-mth));
mth=if(above(mth,6),6,mth);
mres=mpulse*sin(pulse+le*.5) + bnot(mpulse)*mres;



pulse=if(above(abs(pulse),3.14),-3.14,pulse+(bth+mth+tth)*.003);
q1=bres;
q2=tres;
q3=mres;
q4=sin(pulse);

mod_state=(above(q1,0)+above(q2,0)+above(q3,0))*(1+above(q4,0));
ccl=ccl+tpulse+mpulse-bpulse;
q5=cos(pulse*(.5+.1*mod_state));
q6=sin(pulse*(.5+pow(.25,mod_state)));
q7=mod_state;
q8=ccl;
ob_r=.5+.5*cos(q1+q7);
ob_g=.5+.5*cos(q2*3.14+q7);
ob_b=.5+.5*cos(q3*2+sin(time*.0816));
ib_size=.025+.02*q2;
ob_size=.03+.02*q3-.002*q7;
wave_r=.5+.5*sin(q1*q7+time*2.183);
wave_g=.5+.5*sin(q2*3+time*1.211);
wave_b=.5+.5*sin(q3+time*1.541);
ob_a=.8+.2*q2;

preset.pixel_eqs_eel:
snee=bnot(above(sin(ang)-x,.5)*above(q2,0)+above(y-cos(ang),.5)*above(q1,0));
snur=bnot(below(x,.5)*above(q3,0)+below(y,.5)*below(q7,4));
grid=sin(sigmoid(sin(y*6.28*q2),sin(x*6.28*q6))*(10+q7));
rot=bnot(above(x,.5)+((y*q8)%q7))
*cos(rad+3.14*if(above(grid,0),snur,bnot(snur))*(.5+.5*sin(rad*3.14*q1)))*q4;
zoom=zoom+.003*sin(rad*2+rad*q2)*sign(snee)-.003*cos(rad*2*q3);
rot=if(rot,rot*sign(snur),q6*sign(-snur));
cx=if(below(x,.5)*above(y,.5),.5+.5*sin(ang*q1),.5);
cy=if(below(x,.5)*below(y,.5),.5+.5*sin(ang*q3),.5);
sx=sx+.37*sin(rad)*q1*grid*(1-abs(rot));
sy=sy+.37*sin(rad)*q2*grid*(1-abs(rot));
grid=pow(x*3,3-q1)%q8 + pow(y*3,3-q3)%q8;
bend = sin(x*(9.42-6.28*q2)*bnot(q8%3)
+(rad*9.42-6.28*sin(time*(1.3+.3*q1)))*bnot(q8%4)+y*(9.42*q4-6.28*q3)*bnot(q8%5));
zoom = zoom+bend*below(y,.5)*below(x,.5)*.1;
sx=sx-if(above(q7,3),bnot(grid)*q3*.2,.1*q2*bnot(q8%5));
sy=sy-if(below(q7,3),bnot(grid)*q2*.2,.1*q3*bnot(q8%2));
rot=if(equal(grid,3),rot,bnot(grid%q7)*above(x,.5)*above(y,.5)*sin(zoom*rad*3.14));
band1 = below(x,0.1)*above(y,abs(q1-q3))*below(y,abs(q1+q3)*.5);
band2 = below(x,0.1)*above(y,abs(q2-q4))*below(y,abs(q2+q4)*.5);
bases = below(x,0.04)*if(above(q1,q2),above(y,abs(q2))*below(y,abs(q1)),above(y,abs(q1))*below(y,abs(q2)));
bandmove = 0.009*(abs(q5)*band1 + (1-abs(q5))*band2);
basemove = 0.02*bases;
dx = 0.0015*max(bass_att*2,1) + if(above(q7%3,0),basemove,bandmove);
